initJs:
function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentPrediction = null;

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品データを読み込み
  function loadProducts(storeId = '', categoryId = '', searchTerm = '') {
    const tbody = container.querySelector('#product-tbody');
    const productTable = tables.find(t => t.tableName === '商品マスタ');

    if (!productTable || !productTable.records) {
      tbody.innerHTML = '<tr><td colspan="7" class="muted">商品データがありません</td></tr>';
      return;
    }

    let filteredProducts = productTable.records.filter(product => product.有効フラグ);

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(product => 
        product.商品名.toLowerCase().includes(searchTerm.toLowerCase()) ||
        product.商品コード.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    tbody.innerHTML = filteredProducts.map(product => `
      <tr class="product-row" data-id="${product.商品ID}">
        <td><input type="radio" name="product-select" value="${product.商品ID}"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名 || ''}</td>
        <td>カテゴリ${Math.floor(Math.random() * 5) + 1}</td>
        <td>¥${product.単価 || 0}</td>
        <td>¥${product.販売価格 || 0}</td>
        <td>${product.リードタイム日数 || 0}日</td>
      </tr>
    `).join('');
  }

  // バリデーション関数
  function validateForm() {
    let isValid = true;

    // 店舗選択チェック
    const storeSelect = container.querySelector('#store-select');
    const storeError = container.querySelector('#store-error');
    if (!storeSelect.value) {
      storeError.classList.remove('hidden');
      isValid = false;
    } else {
      storeError.classList.add('hidden');
    }

    // 商品選択チェック
    const productSelected = container.querySelector('input[name="product-select"]:checked');
    const productError = container.querySelector('#product-error');
    if (!productSelected) {
      productError.classList.remove('hidden');
      isValid = false;
    } else {
      productError.classList.add('hidden');
    }

    // 期間チェック
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const periodStartError = container.querySelector('#period-start-error');
    const periodEndError = container.querySelector('#period-end-error');

    if (!periodStart.value) {
      periodStartError.classList.remove('hidden');
      isValid = false;
    } else {
      periodStartError.classList.add('hidden');
    }

    if (!periodEnd.value) {
      periodEndError.classList.remove('hidden');
      isValid = false;
    } else {
      periodEndError.classList.add('hidden');
    }

    // 在庫数チェック
    const currentStock = container.querySelector('#current-stock');
    const stockError = container.querySelector('#stock-error');
    if (currentStock.value < 0 || isNaN(currentStock.value)) {
      stockError.classList.remove('hidden');
      isValid = false;
    } else {
      stockError.classList.add('hidden');
    }

    // 安全在庫チェック
    const safetyStock = container.querySelector('#safety-stock');
    const safetyError = container.querySelector('#safety-error');
    if (isNaN(safetyStock.value) || safetyStock.value === '') {
      safetyError.classList.remove('hidden');
      isValid = false;
    } else {
      safetyError.classList.add('hidden');
    }

    // リードタイムチェック
    const leadTime = container.querySelector('#lead-time');
    const leadTimeError = container.querySelector('#leadtime-error');
    if (leadTime.value < 1 || leadTime.value > 365 || isNaN(leadTime.value)) {
      leadTimeError.classList.remove('hidden');
      isValid = false;
    } else {
      leadTimeError.classList.add('hidden');
    }

    // 季節補正係数チェック
    const seasonalFactor = container.querySelector('#seasonal-factor');
    const seasonalError = container.querySelector('#seasonal-error');
    if (seasonalFactor.value < 0.01 || seasonalFactor.value > 9.99 || isNaN(seasonalFactor.value)) {
      seasonalError.classList.remove('hidden');
      isValid = false;
    } else {
      seasonalError.classList.add('hidden');
    }

    // 手動調整発注量チェック
    const manualQty = container.querySelector('#manual-order-qty');
    const manualError = container.querySelector('#manual-error');
    if (manualQty.value && (manualQty.value < 0 || isNaN(manualQty.value))) {
      manualError.classList.remove('hidden');
      isValid = false;
    } else {
      manualError.classList.add('hidden');
    }

    return isValid;
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!validateForm()) return;

    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 1;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // 基本需要量（サンプル計算）
    const baseDemand = 100; // 実際はAI予測値を使用

    // 影響度調整
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;

    // リードタイム期間の需要
    const leadTimeDemand = adjustedDemand * (leadTime / 7); // 週単位で計算

    // AI推奨発注量
    const aiRecommended = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 結果表示
    container.querySelector('#ai-recommended-qty').textContent = aiRecommended;

    // 手動調整値がある場合はそれを、なければAI推奨値を最終値とする
    const manualQty = container.querySelector('#manual-order-qty').value;
    const finalQty = manualQty ? parseInt(manualQty) : aiRecommended;
    container.querySelector('#final-order-qty').textContent = finalQty;

    // 予測結果も更新
    container.querySelector('#predicted-demand').textContent = Math.ceil(adjustedDemand);
    container.querySelector('#prediction-accuracy').textContent = '85%';
    container.querySelector('#recommended-order').textContent = aiRecommended;
  }

  // AI予測実行
  function executeAIPrediction() {
    const storeSelect = container.querySelector('#store-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');

    if (!storeSelect.value || !periodStart.value || !periodEnd.value) {
      if (!periodStart.value || !periodEnd.value) {
        container.querySelector('#period-start-error').classList.remove('hidden');
        container.querySelector('#period-end-error').classList.remove('hidden');
      }
      return;
    }

    // サンプル予測結果を表示
    container.querySelector('#predicted-demand').textContent = '120';
    container.querySelector('#prediction-accuracy').textContent = '87%';
    container.querySelector('#recommended-order').textContent = '85';
  }

  // 初期化
  loadStores();
  loadProducts();

  // スライダーの値表示更新
  container.querySelector('#weather-impact').addEventListener('input', (e) => {
    container.querySelector('#weather-value').textContent = e.target.value + '%';
  });

  container.querySelector('#event-impact').addEventListener('input', (e) => {
    container.querySelector('#event-value').textContent = e.target.value + '%';
  });

  // 商品検索
  container.querySelector('#btn-product-search').addEventListener('click', () => {
    const searchTerm = container.querySelector('#product-search').value;
    loadProducts('', '', searchTerm);
  });

  // 絞り込み実行
  container.querySelector('#btn-filter').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchTerm = container.querySelector('#product-search').value;
    loadProducts(storeId, categoryId, searchTerm);
  });

  // AI予測実行
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);

  // 計算実行
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択時の処理
  container.addEventListener('change', (e) => {
    if (e.target.name === 'product-select') {
      selectedProduct = e.target.value;
      container.querySelector('#product-error').classList.add('hidden');

      // 選択行のハイライト
      container.querySelectorAll('.product-row').forEach(row => {
        row.classList.remove('selected');
      });
      e.target.closest('tr').classList.add('selected');
    }
  });

  // 手動調整値変更時の最終発注量更新
  container.querySelector('#manual-order-qty').addEventListener('input', (e) => {
    const manualQty = parseInt(e.target.value);
    const aiQty = parseInt(container.querySelector('#ai-recommended-qty').textContent) || 0;

    if (manualQty >= 0) {
      container.querySelector('#final-order-qty').textContent = manualQty || aiQty;
      container.querySelector('#manual-error').classList.add('hidden');
    }
  });
}
